const body = $json.body ?? $json;
const fields = body.workflowFields ?? body;
const text = (value) => String(value ?? '').trim();
const required = ['Role_ID','Created_At','Status','Last_Updated_At','Last_Updated_By_Name','Last_Updated_By_Email','Latest_Comments','Resume_Target_Status'];
for (const field of required) if (typeof fields[field] !== 'string') throw new Error(`Missing server-generated field: ${field}`);
if (fields.Status !== 'Pending HR Discussion') throw new Error('New role requests must start at Pending HR Discussion');
const role = body.role ?? {};
const requiredRoleFields = [['Job_Description', role.jobDescription],['Job_Title', role.jobTitle],['Department', role.department],['Number_Of_Vacancies', role.numberOfVacancies],['Reason_For_Request', role.reasonForRequest],['Target_Hiring_Date', role.targetHiringDate]];
const missingFields = requiredRoleFields.filter(([, value]) => text(value) === '').map(([name]) => name);
if (missingFields.length) throw new Error(`REQUISITION_INCOMPLETE: ${missingFields.join(', ')}`);
const requester = body.requester ?? {};
const submittedBy = body.submittedBy ?? {};
const row = {Request_Type:role.requestType??'',Department:role.department??'',Job_Title:role.jobTitle??'',Number_Of_Vacancies:role.numberOfVacancies??'',Reason_For_Request:role.reasonForRequest??'',Job_Description:role.jobDescription??'',Replacement_Employee:role.replacementEmployee??'',Target_Hiring_Date:role.targetHiringDate??'',HOD_Email:fields.HOD_Email??role.hodEmail??'',HOD_Availability_Dates:role.hodAvailabilityDates??'',HOD_Availability_Times:role.hodAvailabilityTimes??'',Custom_Screening_Question_1:role.customScreeningQuestion1??'',Custom_Screening_Question_2:role.customScreeningQuestion2??'',AI_Screening_Questions:(role.aiGeneratedScreeningQuestions??[]).slice(0,5).join('\n'),Reporting_Manager:role.reportingManager??'',Work_Location:role.workLocation??'',Employment_Type:role.employmentType??'',Job_Responsibilities:role.jobResponsibilities??'',Required_Skills:role.requiredSkills??'',Experience_Required:role.experienceRequired??'',Education_Requirements:role.educationRequirements??'',Preferred_Qualifications:role.preferredQualifications??'',Role_Expectations:role.roleExpectations??'',Salary_Min:role.salaryMin??'',Salary_Max:role.salaryMax??'',Work_Schedule:role.workSchedule??'',Notice_Period_Requirement:role.noticePeriodRequirement??'',Salary_Expectation_Guidance:role.salaryExpectationGuidance??'',Role_ID:fields.Role_ID,Created_At:fields.Created_At,Status:fields.Status,Last_Updated_At:fields.Last_Updated_At,Last_Updated_By_Name:fields.Last_Updated_By_Name,Last_Updated_By_Email:fields.Last_Updated_By_Email,Latest_Comments:fields.Latest_Comments,Resume_Target_Status:fields.Resume_Target_Status,Requester_Name:fields.Requester_Name??requester.name??'',Requester_Email:fields.Requester_Email??requester.email??'',Requester_Type:fields.Requester_Type??requester.type??'',Submitted_By_Name:fields.Submitted_By_Name??submittedBy.name??'',Submitted_By_Email:fields.Submitted_By_Email??submittedBy.email??'',Submission_ID:body.submissionId??fields.Submission_ID??'',Source:body.source??fields.Source??'Role Creation Website',Notification_Status:'pending',Notification_Error:''};
return [{json:row}];

const input = $('Role Request Webhook').item.json.body ?? $('Role Request Webhook').item.json;
const row = $('Validate and Map Role Request').item.json;
const escapeHtml = (value) => String(value ?? '').replace(/[&<>\"']/g, (character) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[character]));
const portalUrl = String(input.portalUrl ?? '').trim();
const roleTitle = escapeHtml(row.Job_Title);
const roleId = escapeHtml(row.Role_ID);
const recipient = 'cs6@mclinkgroup.com';
return [{json:{...row, notificationRecipient:recipient, notificationSubject:`New role request: ${row.Job_Title} (${row.Role_ID})`, notificationMessage:`<p>A new role request was submitted for HR discussion.</p><p><strong>Role:</strong> ${roleTitle}<br><strong>Role ID:</strong> ${roleId}<br><strong>Department:</strong> ${escapeHtml(row.Department)}<br><strong>Requester:</strong> ${escapeHtml(row.Requester_Name)} (${escapeHtml(row.Requester_Email)})<br><strong>Target hiring date:</strong> ${escapeHtml(row.Target_Hiring_Date)}</p>${portalUrl ? `<p><a href=\"${escapeHtml(portalUrl)}\">Open role request in the portal</a></p>` : ''}<p>Regards,<br>McLink Recruitment Portal</p>`}}];

const result = $json;
const error = result.error;
return [{json:{roleId:$('Validate and Map Role Request').item.json.Role_ID,status:$('Validate and Map Role Request').item.json.Status,action:'role_request_created',actionRequestId:$('Role Request Webhook').item.json.body?.submissionId ?? '',notificationStatus:error ? 'failed' : 'sent',notificationError:error ? String(error.message ?? error) : ''}}];
